-- 23-align-remove-surplus.sql  (HCM 2.1)   -- OPTIONAL, DESTRUCTIVE, NOT run by apply.sh
--
-- PURPOSE: bring an EXISTING cluster's UI-driving MDMS masters into exact agreement with hcm-demo by
-- deleting rows that exist locally but do NOT exist on demo.
--
-- WHY IT IS NEEDED. Files 19/20/21 are INSERT ... ON CONFLICT DO UPDATE: they can add a row and correct
-- a row, but they can never REMOVE one. A cluster seeded before this bundle existed keeps its local-only
-- rows through every re-apply, and those render as DUPLICATE CARD TILES and duplicate dropdown options.
-- Measured against the reference environment, 2026-08-20:
--     ACCESSCONTROL-ACTIONS-TEST.actions-test    197 local-only rows (the id-5000 series and others)
--     ACCESSCONTROL-ROLEACTIONS.roleactions      497 local-only rows (they grant the surplus actions)
--     HCM-PROJECT-TYPES.projectTypes               1 local-only row  -> 'Co-Delivery' listed TWICE
--     HCM-ADMIN-CONSOLE.campaignTypeTemplates      1 local-only row  ('Malaria2024')
--   Symptoms: 'My campaigns' x3, 'Create campaign' x3, 'Boundary management' x3, 'Search user' x3,
--   'Create user' x3, 'Setup Payment Attributes' x2, 'Co-Delivery' x2.
--
-- SAFE ON A FRESH INSTALL. A database seeded only from this bundle contains exactly demo's rows, so the
-- DELETEs match nothing and this file is a no-op. It can only ever remove rows that demo does not have.
--
-- SCOPE IS DELIBERATELY NARROW - only the 5 masters that drive menus and dropdowns. It does NOT touch
-- campaign-derived masters (HCM.WORKER_RATES, HCM-ADMIN-CONSOLE.NewFormConfig, NewApkConfig, ...): on a
-- live cluster those belong to that cluster's OWN campaigns and removing them would break them.
--
-- WHAT IT DOES NOT FIX. demo itself carries 173 byte-identical duplicate action rows granted to the same
-- role (ids 2304 and 2330 are both HCMCONSOLE.MY_CAMPAIGNS -> /workbench-ui/employee/campaign/my-campaign-new,
-- both granted to CAMPAIGN_MANAGER). After this script the cluster MATCHES demo, so those tiles still
-- appear twice - exactly as they do on demo. Removing them would be a divergence from demo and is
-- deliberately out of scope here; raise it upstream instead.
--
-- BACK UP FIRST:
--   \copy (SELECT * FROM eg_mdms_data WHERE tenantid='mz' AND schemacode IN ('ACCESSCONTROL-ACTIONS-TEST.actions-test', 'ACCESSCONTROL-ROLEACTIONS.roleactions', 'ACCESSCONTROL-ROLES.roles', 'HCM-PROJECT-TYPES.projectTypes', 'HCM-ADMIN-CONSOLE.campaignTypeTemplates')) TO 'mdms-surplus-backup.csv' CSV HEADER
--
-- RUN:      psql -v ON_ERROR_STOP=1 -h $PGHOST -U $PGUSER -d $PGDATABASE -f 23-align-remove-surplus.sql
-- POST:     kubectl rollout restart deploy/mdms-v2 -n egov
--           then Clear-site-data in the browser (the console caches actions in IndexedDB; a reload is
--           NOT enough).
--
-- Runs in a single transaction: it either fully applies or fully rolls back.

BEGIN;

CREATE TEMP TABLE demo_keep (schemacode text NOT NULL, uniqueidentifier text NOT NULL) ON COMMIT DROP;

