CREATE INDEX ON demo_keep (schemacode, uniqueidentifier);
ANALYZE demo_keep;

-- Report before removing, so the run is auditable in the psql output.
DO $$
DECLARE r record; total int := 0;
BEGIN
  FOR r IN
    SELECT d.schemacode, count(*) AS n
      FROM eg_mdms_data d
     WHERE d.tenantid = 'mz'
       AND d.schemacode IN (SELECT DISTINCT schemacode FROM demo_keep)
       AND NOT EXISTS (SELECT 1 FROM demo_keep k
                        WHERE k.schemacode = d.schemacode
                          AND k.uniqueidentifier = d.uniqueidentifier)
     GROUP BY d.schemacode ORDER BY d.schemacode
  LOOP
    RAISE NOTICE 'surplus (absent on demo): % row(s) in %', r.n, r.schemacode;
    total := total + r.n;
  END LOOP;
  RAISE NOTICE '--> total surplus rows to remove: %', total;
END $$;

DELETE FROM eg_mdms_data d
 WHERE d.tenantid = 'mz'
   AND d.schemacode IN (SELECT DISTINCT schemacode FROM demo_keep)
   AND NOT EXISTS (SELECT 1 FROM demo_keep k
                    WHERE k.schemacode = d.schemacode
                      AND k.uniqueidentifier = d.uniqueidentifier);

-- NOTE - deliberately NOT cleaning up 'dangling' roleactions (rows whose actionid has no matching
-- action). demo itself carries 143 of them, so deleting them would DIVERGE from demo and would break
-- this file's no-op-on-a-fresh-install guarantee. Measured: applying such a cleanup to a database
-- seeded purely from this bundle removed 143 rows. They grant nothing and are harmless.

-- map-config.GeoJsonMapping rows whose KEY embeds the corrupted hcm-mz-assets hostname. An early
-- revision of this bundle ran the demo->mz substitution inside URLs; this master's uniqueidentifier
-- is '<code>.<url>', so the substitution corrupted the key itself and the later, URL-protected
-- upsert could never match those rows again - they survived as a dead second copy pointing at a
-- bucket that does not exist (the real one is hcm-demo-assets). demo has 0 such rows and file 21
-- emits none (its only 'hcm-mz-assets' occurrence is a header comment), so this is a no-op on a
-- fresh install and removes exactly the 21 relics on a cluster seeded with the pre-fix bundle
-- (measured against the reference environment, 2026-08-21: DELETE 21, leaving the 21 correct rows + 6 other-host rows).
DELETE FROM eg_mdms_data
 WHERE schemacode = 'map-config.GeoJsonMapping'
   AND data::text LIKE '%hcm-mz-assets%';

COMMIT;
